#include <bits/stdc++.h>
using namespace std;
typedef pair<int,int> PI;
typedef long long LL;
#define FI first
#define SE second
#define MP make_pair
#define PB push_back
#define R(I,N) for(int I=0;I<N;I++)
#define F(I,A,B) for(int I=A;I<B;I++)
#define FD(I,N) for(int I=N-1;I>=0;I--)
#define input(A) scanf("%d",&A)
#define inputPair(A,B) scanf("%d%d",&A,&B)
const int MAX = 31;
const int P = 1e9 + 7;
int n;
LL matrix[MAX][MAX];
struct Mat {
    LL t[MAX][MAX];
    void setIdentity() {
        R(i,n) R(j,n) t[i][j] = (i==j);
    }
    void multiply(Mat& b) {
        R(i,n) R(j,n) matrix[i][j] = 0;
        R(i,n) R(j,n) R(k,n)
            matrix[i][k] += t[i][j] * b.t[j][k] % P;
        R(i,n) R(j,n) t[i][j] = matrix[i][j] % P;
    }
};
LL m;
LL powerArr[MAX];
LL answer[MAX];
int k;
vector<LL> digitsVec;
int main() {
    LL m_in; int k_in;
    scanf("%lld%d", &m_in, &k_in);
    m = m_in; k = k_in;
    while (m) {
        digitsVec.PB(m % k);
        m /= k;
    }
    n = k + 1;
    Mat baseMat, idMat;
    R(i,k) baseMat.t[i][(i+1)%k] = 1;
    baseMat.t[k][k] = 1;
    idMat.setIdentity();
    R(i,k+1) {
        baseMat.t[0][i] = 1;
        baseMat.t[i][i] = 1;
    }
    vector<Mat> dMat(digitsVec.size());
    dMat[0] = idMat;
    dMat[0].multiply(baseMat);
    F(i,1,(int)digitsVec.size()) {
        dMat[i] = dMat[i-1];
        R(_,k) dMat[i].multiply(dMat[i]);
        dMat[i].multiply(baseMat);
    }
    R(i,n) answer[i] = 1;
    for (int idx = (int)digitsVec.size() - 1; idx >= 0; idx--) {
        R(_, digitsVec[idx]) {
            R(i,n) powerArr[i] = 0;
            R(i,n) R(j,n) powerArr[j] += answer[i] * dMat[idx].t[i][j] % P;
            R(i,n) answer[i] = powerArr[i] % P;
        }
    }
    printf("%lld\n", answer[k]);
}
